--[[
Generated by the Project Viewpoint ADS bench on 2026-10-12 - do not edit by hand, re-run the bench instead.

Every gun x optic of these packs was loaded with the game's own model importer, the eye placed where the ADS code
places it, and the sight picture drawn from there; each sight's glass was found on its model (lens geometry, glass
painted in its texture, or estimated inside the rim of a closed tube) and the picture-in-picture window fitted to
it: as large as the glass allows without the housing showing inside it.
Rules: (1) the reticle is on the aim point and in the middle of the visible glass (the eye moved to the glass's
centre, never the window off the eye line); (2) iron sights: front post tip on the aim point, rear aperture or notch
centred on it; (3) which way up each model is built is checked (the mod turns upside-down models over in-game).
Packs: Guns of Marz (GunsOfMarz), Guns of Marz (Old Version) (MarzGuns), Vanilla Weapons Plus - Gunworks Edition (MarzVanillaGuns), Vanilla Firearms Expansion (VFExpansion1), Vanilla firearms expansion - STALKER pack (VFExpansion2), Vanilla firearms expansion - Post '93 (VFExpansion3), Totally's Law Enforcement And Criminal Firearms (TCAR), Project Zomboid (vanilla) (vanilla)
Harmless when a pack is not installed: entries are only read for items that exist.
]]
require "PVADS/PVADS_Weapons"
require "PVADS/PVADS_Compat_GunsOfMarz"

local function optic(id, def) PVADS.RegisterOpticProfile(id, def) end
local function pair(gun, id, def) PVADS.RegisterWeaponOpticOverride(gun, id, def) end
local function ironsMesh(gun, mesh, def) PVADS.RegisterIronVariant(gun, mesh, def) end
local function scopeModel(key, def) if PVADS.RegisterOpticModelProfile then PVADS.RegisterOpticModelProfile(key, def) end end
local function irons(gun, def)
    local cur = PVADS.WeaponOptic and PVADS.WeaponOptic[gun] and PVADS.WeaponOptic[gun][""]
    if cur and (cur.adjX or cur.adjY or cur.adjZ or cur.adjPitch or cur.adjYaw or cur.adjRoll) then return end
    PVADS.RegisterWeaponOpticOverride(gun, "", def)
end

